function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith('sb_publishable_') || value.startsWith('sb_secret_');
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return (input, init) => {
    const headers = new Headers(
      typeof Request !== 'undefined' && input instanceof Request ? input.headers : undefined,
    );

    if (init?.headers) {
      new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    }

    // New Supabase API keys are opaque strings, not bearer JWTs.
    if (isNewSupabaseApiKey(supabaseKey) && headers.get('Authorization') === `Bearer ${supabaseKey}`) {
      headers.delete('Authorization');
    }

    headers.set('apikey', supabaseKey);
    return fetch(input, { ...init, headers });
  };
}

export const requireSupabaseAuthBasic = createMiddleware({ type: 'function' }).server(
  async ({ next }) => {
    
    const SUPABASE_URL = process.env['SUPABASE_URL'];
    const SUPABASE_PUBLISHABLE_KEY = process.env['SUPABASE_PUBLISHABLE_KEY'];

    if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
      const missing = [
        ...(!SUPABASE_URL ? ['SUPABASE_URL'] : []),
        ...(!SUPABASE_PUBLISHABLE_KEY ? ['SUPABASE_PUBLISHABLE_KEY'] : []),
      ];
      const message = `Missing Supabase environment variable(s): ${missing.join(', ')}. Configure the deployment environment.`;
      console.error(`[Supabase] ${message}`);
      throw new Error(message);
    }
    
    const request = getRequest();

    if (!request?.headers) {
      throw new Error('Unauthorized: No request headers available');
    }


    const authHeader = request.headers.get('authorization');

    if (!authHeader) {
      throw new Error('Unauthorized: No authorization header provided');
    }

    if (!authHeader.startsWith('Bearer ')) {
      throw new Error('Unauthorized: Only Bearer tokens are supported');
    }

    const token = authHeader.replace('Bearer ', '');
    if (!token) {
      throw new Error('Unauthorized: No token provided');
    }

    if (token.split('.').length !== 3) {
      throw new Error('Unauthorized: Invalid token');
    }

    const supabase = createClient<Database>(
      SUPABASE_URL!,
      SUPABASE_PUBLISHABLE_KEY!,
      {
        global: {
          fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY!),
          headers: {
            Authorization: `Bearer ${token}`,
          },
        },
        auth: {
          storage: undefined,
          persistSession: false,
          autoRefreshToken: false,
        },
      }
    );

    const claims = await requireActiveSupabaseSession(supabase, token);

    return next({
      context: {
        supabase,
        userId: claims.sub,
        claims,
      },
    });
  },
);

// Once enabled, staff must establish a session-bound IdP proof for server functions.
// Onboarding/linking uses the basic middleware but never grants corporate data access.
export const requireSupabaseAuth = createMiddleware({ type: 'function' })
  .middleware([requireSupabaseAuthBasic])
  .server(async ({ next, context }) => {
    const { supabaseAdmin } = await import('./client.server');
    const settings = await supabaseAdmin.from('staff_security_settings').select('enforced').eq('id',true).single();
    if (settings.error || !settings.data) throw new Error('STAFF_SECURITY_CONFIGURATION_REQUIRED');
    if (process.env.STAFF_SSO_ENFORCED === 'true' || (settings.data as { enforced: boolean }).enforced) {
      const [user, admin] = await Promise.all([
        supabaseAdmin.auth.admin.getUserById(context.userId),
        supabaseAdmin.from('platform_admins').select('active').eq('user_id', context.userId).maybeSingle(),
      ]);
      if (user.error || admin.error) throw new Error('STAFF_ACCESS_CHECK_FAILED');
      if (user.data.user?.app_metadata?.corporate_admin === true || admin.data?.active === true) {
        const { getCookie } = await import('@tanstack/react-start/server');
        const { STAFF_COOKIE, verifyStaffSession } = await import('@/lib/staff-session.server');
        if (!verifyStaffSession(getCookie(STAFF_COOKIE), context.userId, String(context.claims.session_id || ''), process.env.STAFF_SESSION_SIGNING_KEY || '')) throw new Error('STAFF_SSO_REQUIRED');
        const proof = await supabaseAdmin.from('staff_sso_sessions' as never).select('expires_at').eq('session_id', String(context.claims.session_id || '')).eq('user_id', context.userId).maybeSingle();
        const expires = proof.data && Date.parse((proof.data as { expires_at: string }).expires_at);
        if (proof.error || !expires || !Number.isFinite(expires) || expires <= Date.now()) throw new Error('STAFF_SSO_REQUIRED');
      }
    }
    return next({ context });
  });
